import{_ as d,C as E,o as e,c as r,a2 as l,b as n,w as o,a as s,E as C,a3 as i}from"./chunks/framework.CZGNF-7T.js";const y=JSON.parse('{"title":"회사 인장 및 전결선 관리 (관리부서 가이드)","description":"","frontmatter":{},"headers":[],"relativePath":"authority/company-seal.md","filePath":"authority/company-seal.md","lastUpdated":1789180953000}'),c={name:"authority/company-seal.md"};function B(A,t,g,_,f,h){const a=E("Mermaid");return e(),r("div",null,[t[1]||(t[1]=l('<h1 id="회사-인장-및-전결선-관리-관리부서-가이드" tabindex="-1">회사 인장 및 전결선 관리 (관리부서 가이드) <a class="header-anchor" href="#회사-인장-및-전결선-관리-관리부서-가이드" aria-label="Permalink to &quot;회사 인장 및 전결선 관리 (관리부서 가이드)&quot;">​</a></h1><blockquote><p><strong>회사 인장 관리</strong>는 본사 관리부서(경영지원본부, 총무팀, 법무팀 등)가 법인인감, 사용인감, 현장소장 직인, 전결권자 서명 등을 시스템에 정식 등록하고, 각 인장별 **허용 전결 자격(결재 규정)**을 사전에 설정하여 인장 오남용과 권한 월권을 원천 통제하는 관리자 전용 기능입니다.</p></blockquote><ul><li><strong>관리 위치</strong>: <ul><li>Django Admin 백오피스: <code>01. 회사 및 조직 관리 &gt; 03. 회사 인장</code> (<code>/admin/company/companyseal/</code>)</li><li>또는 <code>회사 정보</code> 상세 페이지 내 <code>회사 인장 (CompanySeal)</code> 인라인 목록</li></ul></li><li><strong>관리 주체</strong>: 본사 인장 관리 부서 담당자, 최고 관리자 (<code>is_superuser</code>, <code>is_staff</code>)</li></ul><h2 id="_1-인장-관리-아키텍처-및-통제-원칙" tabindex="-1">1. 인장 관리 아키텍처 및 통제 원칙 <a class="header-anchor" href="#_1-인장-관리-아키텍처-및-통제-원칙" aria-label="Permalink to &quot;1. 인장 관리 아키텍처 및 통제 원칙&quot;">​</a></h2><p>회사의 도장과 서명은 대외적인 법적 권리의무를 발생시키는 핵심 자산이므로, 일반 사용자가 임의로 등록할 수 없으며 <strong>관리부서의 정식 등록 절차를 통해서만 시스템에 편입</strong>됩니다.</p>',5)),(e(),n(i,null,{default:o(()=>[C(a,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%ED%98%84%EC%9E%A5%20%2F%20%EC%82%AC%EC%97%85%EB%B3%B8%EB%B6%80%3Cbr%3E(%EC%9D%B8%EC%9E%A5%20%EC%82%AC%EC%9A%A9%20%EB%B6%80%EC%84%9C)%22%5D%20--%3E%7C%EC%9D%B8%EC%9E%A5%20%EB%93%B1%EB%A1%9D%20%EC%9A%94%EC%B2%AD%7C%20B%5B%22%EB%B3%B8%EC%82%AC%20%EA%B4%80%EB%A6%AC%EB%B6%80%EC%84%9C%3Cbr%3E(%EC%B4%9D%EB%AC%B4%20%2F%20%EB%B2%95%EB%AC%B4%20%2F%20%EA%B2%BD%EC%98%81%EC%A7%80%EC%9B%90)%22%5D%0A%20%20%20%20B%20--%3E%7C%221.%20%EC%A0%95%EC%8B%9D%20%EC%9D%B8%EC%9E%A5%20%EB%93%B1%EB%A1%9D%3Cbr%3E(CompanySeal%20%EB%AA%A8%EB%8D%B8)%22%7C%20C%7B%222.%20%EC%9D%B8%EC%9E%A5%20%EC%A2%85%EB%A5%98%20%26%20%EC%A0%84%EA%B2%B0%20%EA%B8%B0%EC%A4%80%20%EC%84%A4%EC%A0%95%22%7D%0A%20%20%20%20C%20--%20%22%EB%B2%95%EC%9D%B8%EC%9D%B8%EA%B0%90%20%2F%20%EC%82%AC%EC%9A%A9%EC%9D%B8%EA%B0%90%22%20--%3E%20D%5B%22%EB%8C%80%ED%91%9C%EC%9D%B4%EC%82%AC%20%EA%B2%B0%EC%9E%AC%20%ED%95%84%EC%88%98%3Cbr%3E(%EC%A0%84%EA%B2%B0%20%EB%B6%88%EA%B0%80%20%ED%86%B5%EC%A0%9C)%22%5D%0A%20%20%20%20C%20--%20%22%ED%98%84%EC%9E%A5%EC%86%8C%EC%9E%A5%20%EC%A7%81%EC%9D%B8%20%2F%20%EB%B6%80%EC%84%9C%EC%9D%B8%EA%B0%90%22%20--%3E%20E%5B%22%ED%98%84%EC%9E%A5%EC%86%8C%EC%9E%A5%20%2F%20%EB%B6%80%EC%84%9C%EC%9E%A5%20%EC%A0%84%EA%B2%B0%20%ED%97%88%EC%9A%A9%3Cbr%3E(final_approval_duty%20%EB%A7%A4%ED%95%91)%22%5D%0A%20%20%20%20D%20%26%20E%20--%3E%20F%5B%22%EA%B3%B5%EB%AC%B8%20%EB%B0%9C%EC%86%A1%20%EC%8B%9C%20%EC%9E%90%EB%8F%99%20%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EC%82%B0%EC%B6%9C%3Cbr%3E%26%20%EC%9D%B8%EC%9E%A5%20%EC%98%A4%EB%82%A8%EC%9A%A9%20%EC%9B%90%EC%B2%9C%20%EC%B0%A8%EB%8B%A8%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_2-인장-등록-시-필수-입력-항목-가이드" tabindex="-1">2. 인장 등록 시 필수 입력 항목 가이드 <a class="header-anchor" href="#_2-인장-등록-시-필수-입력-항목-가이드" aria-label="Permalink to &quot;2. 인장 등록 시 필수 입력 항목 가이드&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">필드명</th><th style="text-align:left;">영문 필드</th><th style="text-align:left;">설명 및 설정 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>회사</strong></td><td style="text-align:left;"><code>company</code></td><td style="text-align:left;">해당 인장이 귀속되는 소속 법인 선택</td></tr><tr><td style="text-align:left;"><strong>인장 종류</strong></td><td style="text-align:left;"><code>seal_type</code></td><td style="text-align:left;">• <code>CORP_SEAL</code>: 법인인감 (대표이사 직인)<br>• <code>USAGE_SEAL</code>: 사용인감 (계약/분양 전용 등)<br>• <code>DEPT_SEAL</code>: 부서인감 / 현장소장 직인<br>• <code>SIGN</code>: 대표자 / 현장소장 전자 서명<br>• <code>OMIT</code>: 직인생략</td></tr><tr><td style="text-align:left;"><strong>인장 명칭</strong></td><td style="text-align:left;"><code>name</code></td><td style="text-align:left;">사용자가 쉽게 식별할 수 있는 명칭 (예: <code>[판교현장] 현장소장인</code>, <code>대표이사 법인인감</code>)</td></tr><tr><td style="text-align:left;"><strong>인장 이미지</strong></td><td style="text-align:left;"><code>seal_image</code></td><td style="text-align:left;"><strong>배경이 투명한 PNG 형식(정방형 비율)</strong> 권장 (PDF 인쇄 시 문서 배경과 자연스럽게 합성됨)</td></tr><tr><td style="text-align:left;"><strong>관리 책임자/부서</strong></td><td style="text-align:left;"><code>manager</code></td><td style="text-align:left;">해당 실물 인장을 보관/관리하는 책임자 (예: <code>판교복합개발현장 현장소장 홍길동</code>)</td></tr><tr><td style="text-align:left;"><strong>전결 직책 자격</strong></td><td style="text-align:left;"><code>final_approval_duty</code></td><td style="text-align:left;"><strong>🌟 핵심 통제 필드</strong>: 이 인장이 날인되기 위해 필요한 <strong>최소 최종 전결 직책</strong> 지정<br>• <code>현장소장</code>/<code>팀장</code>: 현장소장 승인으로 결재 종결 가능<br>• <code>미지정(빈칸)</code>: 대표이사까지 결재선이 반드시 상신됨</td></tr><tr><td style="text-align:left;"><strong>전결 부서 레벨</strong></td><td style="text-align:left;"><code>final_dept_level</code></td><td style="text-align:left;">예: <code>1</code>로 설정 시 본부장(1레벨) 승인으로 결재 종결 가능</td></tr><tr><td style="text-align:left;"><strong>사용 여부</strong></td><td style="text-align:left;"><code>is_active</code></td><td style="text-align:left;">폐기되거나 분실/재발급된 인장은 체크 해제하여 사용 중단 처리</td></tr></tbody></table><h2 id="_3-현장소장-전결-공문-vs-대표이사-승인-공문-분기-메커니즘" tabindex="-1">3. 현장소장 전결 공문 vs 대표이사 승인 공문 분기 메커니즘 <a class="header-anchor" href="#_3-현장소장-전결-공문-vs-대표이사-승인-공문-분기-메커니즘" aria-label="Permalink to &quot;3. 현장소장 전결 공문 vs 대표이사 승인 공문 분기 메커니즘&quot;">​</a></h2><p>단일한 공문서 양식(<code>OFFICIAL_LETTER</code>) 내에서도 관리부서가 지정한 인장의 전결 기준에 따라 결재선이 지능적으로 자동 분기됩니다:</p><h3 id="_1-대표이사-법인인감-corp-seal-등록-시" tabindex="-1">1) 대표이사 법인인감 (<code>CORP_SEAL</code>) 등록 시 <a class="header-anchor" href="#_1-대표이사-법인인감-corp-seal-등록-시" aria-label="Permalink to &quot;1) 대표이사 법인인감 (`CORP_SEAL`) 등록 시&quot;">​</a></h3><ul><li><code>final_approval_duty</code>: **미지정(빈칸)**으로 보관</li><li><strong>동작</strong>: 기안자가 해당 인장을 선택하면 시스템은 자동으로 대표이사까지 결재선을 연결하며, <strong>대표이사 최종 승인이 떨어지기 전에는 인장이 날인되지 않습니다.</strong></li></ul><h3 id="_2-현장소장-직인-부서장-직인-dept-seal-등록-시" tabindex="-1">2) 현장소장 직인 / 부서장 직인 (<code>DEPT_SEAL</code>) 등록 시 <a class="header-anchor" href="#_2-현장소장-직인-부서장-직인-dept-seal-등록-시" aria-label="Permalink to &quot;2) 현장소장 직인 / 부서장 직인 (`DEPT_SEAL`) 등록 시&quot;">​</a></h3><ul><li><code>final_approval_duty</code>: <strong><code>현장소장</code></strong> (또는 <code>팀장</code>, <code>본부장</code> 등 전결 가능 직책)으로 지정</li><li><strong>동작</strong>: 공문 작성자가 이 인장을 선택하여 상신하면, 결재선이 해당 현장소장 단계에서 자동으로 종결(전결)되어 대표이사에게 올라가지 않고 신속하게 처리됩니다.</li></ul><h2 id="_4-관리부서-실무-유의사항" tabindex="-1">4. 관리부서 실무 유의사항 <a class="header-anchor" href="#_4-관리부서-실무-유의사항" aria-label="Permalink to &quot;4. 관리부서 실무 유의사항&quot;">​</a></h2><ol><li><strong>실물 인감 날인 스캔본 관리</strong>: <ul><li>대외 기관 제출용으로 출력 후 실물 도장을 직접 찍어 발송하는 경우, 공문서의 인장은 <code>인장 미선택 / (직인생략 / 출력 후 실물날인)</code>으로 기안하도록 안내하십시오.</li><li>발송 후에는 반드시 실제 날인된 종이를 스캔하여 <strong>스캔본(PDF)으로 업로드</strong>하도록 지도해야 대장 보존 무결성이 확보됩니다.</li></ul></li><li><strong>발송 완료 후 증빙 보호</strong>: <ul><li>발송이 완료된 공문서는 어떠한 경우에도 시스템 PDF 재생성(템플릿 덮어쓰기)이 차단됩니다.</li><li>이미 발송된 공문의 스캔본을 불가피하게 교체해야 할 때는 일반 사용자 권한으로는 불가능하며, **관리부서(슈퍼유저/워크매니저)**가 내용 확인 후 직접 교체 처리해야 합니다.</li></ul></li></ol>',10))])}const u=d(c,[["render",B]]);export{y as __pageData,u as default};
